    SELECT
        'PRJT'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(PRJ_NO), LENGTH('PRJT' ) + 1)), 0) + 1, 6, '0')
    FROM PROJECT

INSERT INTO PROJECT (
	PRJ_NO
	, USER_ID
	, PROJECT_BOARD_NO
	, PROJECT_NAME
	, PROJECT_CONTENTS
	, PROJECT_STATUS
	, CREATE_DATE
) VALUES (
	#{prjNo}
	, #{userId}
	, #{projectBoardNo}
	, #{projectName}
	, #{projectContents}
	, #{projectStatus}
	, SYSDATE
)

